          <button
            type="button"
            role="radio"
            aria-checked={settings.theme === 'dark'}
            className={`btn-option ${settings.theme === 'dark' ? 'btn-active' : ''}`}
            onClick={() => handleThemeChange('dark')}
          >
            ダークネオン
          </button>
          <button
            type="button"
            role="radio"
            aria-checked={settings.theme === 'wood'}
            className={`btn-option ${settings.theme === 'wood' ? 'btn-active' : ''}`}
