          <button
            type="button"
            role="radio"
            aria-checked={settings.movement === 'smooth'}
            className={`btn-option ${settings.movement === 'smooth' ? 'btn-active' : ''}`}
            onClick={() => handleMovementChange('smooth')}
          >
            スイープ（滑らか）
          </button>
          <button
            type="button"
            role="radio"
            aria-checked={settings.movement === 'step'}
            className={`btn-option ${settings.movement === 'step' ? 'btn-active' : ''}`}
            onClick={() => handleMovementChange('step')}
          >
            ステップ（1秒刻み）
          </button>
        </div>
      </div>

      {/* トグルスイッチ群 */}
      <div className="control-group">
        <span className="control-label">表示・サウンド設定</span>

        {/* デジタル時計表示トグル */}
        <label className="toggle-container" htmlFor="toggle-digital-time">
          <span className="toggle-label">デジタル時刻を表示</span>
          <div className="toggle-switch">
