import React, { useState, useEffect, useRef, useCallback } from 'react';
import AnalogClock from './components/AnalogClock';
import ClockControls from './components/ClockControls';
import { ClockSettings } from './types';
import './index.css';

interface TimeState {
  hours: number;
  minutes: number;
  seconds: number;
  milliseconds: number;
  day: number;
  fullDateString: string;
}

const DEFAULT_SETTINGS: ClockSettings = {
  theme: 'classic',
  movement: 'smooth',
  showDigital: true,
  showDate: true,
  soundEnabled: false,
  is24Hour: true,
};

const WEEKDAYS = ['日', '月', '火', '水', '木', '金', '土'];

// ClockControlsの不要な高頻度再レンダリングを防止するためのメモ化
const MemoizedClockControls = React.memo(ClockControls);

export default function App() {
  const [settings, setSettings] = useState<ClockSettings>(DEFAULT_SETTINGS);
  const [timeState, setTimeState] = useState<TimeState>(() => {
    const now = new Date();
    return {
      hours: now.getHours(),
      minutes: now.getMinutes(),
      seconds: now.getSeconds(),
      milliseconds: now.getMilliseconds(),
      day: now.getDate(),
      fullDateString: `${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日 (${WEEKDAYS[now.getDay()]})`,
    };
  });

  const lastSecondRef = useRef<number>(-1);
  const audioContextRef = useRef<AudioContext | null>(null);

  // Web Audio API によるチクタク効果音生成
  const playTickSound = useCallback((isTock: boolean) => {
    try {
      const AudioCtx =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (!AudioCtx) return;

      if (!audioContextRef.current) {
        audioContextRef.current = new AudioCtx();
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') {
        ctx.resume();
      }

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      // チク (高音 880Hz) / タク (低音 650Hz)
      osc.type = 'sine';
      osc.frequency.setValueAtTime(isTock ? 650 : 880, ctx.currentTime);

      gain.gain.setValueAtTime(0.045, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.035);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.04);
    } catch {
      // オーディオ未許可時のサイレントキャッチ
    }
  }, []);

  // コンポーネントアンマウント時に AudioContext を close してリソースリークを防止
  useEffect(() => {
    return () => {
      if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
        audioContextRef.current.close().catch(() => {});
        audioContextRef.current = null;
      }
    };
  }, []);

  // requestAnimationFrame による高精度なリアルタイムレンダーループ
  // movement が step の場合は秒変化時のみ更新することで不要な再描画を抑制
  useEffect(() => {
    let animationFrameId: number;

    const updateClock = () => {
      const now = new Date();
      const hours = now.getHours();
      const minutes = now.getMinutes();
      const seconds = now.getSeconds();
      const milliseconds = now.getMilliseconds();
      const day = now.getDate();

      const secondChanged = seconds !== lastSecondRef.current;

      // 秒が切り替わったタイミングでチクタク音を再生
      if (secondChanged) {
        if (settings.soundEnabled && lastSecondRef.current !== -1) {
          playTickSound(seconds % 2 === 0);
        }
        lastSecondRef.current = seconds;
      }

      // スムーズ運針時は毎フレーム、ステップ運針時は秒変化時のみ state を更新しCPU負荷を軽減
      if (settings.movement === 'smooth' || secondChanged) {
        const dateStr = `${now.getFullYear()}年${now.getMonth() + 1}月${day}日 (${WEEKDAYS[now.getDay()]})`;

        setTimeState({
          hours,
          minutes,
          seconds,
          milliseconds,
          day,
          fullDateString: dateStr,
        });
      }

      animationFrameId = requestAnimationFrame(updateClock);
    };

    animationFrameId = requestAnimationFrame(updateClock);

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [settings.soundEnabled, settings.movement, playTickSound]);

  const handleUpdateSettings = useCallback((newSettings: Partial<ClockSettings>) => {
    setSettings((prev) => {
      const updated = { ...prev, ...newSettings };
      // ユーザー操作時にオーディオコンテキストをアクティベート
      if (newSettings.soundEnabled && !audioContextRef.current) {
        try {
          const AudioCtx =
            window.AudioContext ||
            (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
          if (AudioCtx) {
            audioContextRef.current = new AudioCtx();
          }
        } catch {
          // 無視
        }
      }
      return updated;
    });
  }, []);

  // ゼロ埋めフォーマット
  const padZero = (n: number) => n.toString().padStart(2, '0');

  // 12時間/24時間表示フォーマット
  const is24HourMode = settings.is24Hour !== false;
  const displayHours = is24HourMode
    ? padZero(timeState.hours)
    : padZero(timeState.hours % 12 === 0 ? 12 : timeState.hours % 12);
  const ampmIndicator = !is24HourMode ? (timeState.hours >= 12 ? 'PM' : 'AM') : null;
  const digitalTimeStr = `${displayHours}:${padZero(timeState.minutes)}:${padZero(timeState.seconds)}`;
  const dateWindowText = `${timeState.day}`;

  return (
    <div className="app-wrapper">
      <main className="clock-app-container">
        {/* ヘッダー */}
        <header className="app-header">
          <h1 className="app-title">Precision Analog Clock</h1>
          <p className="app-subtitle">高精度リアルタイム アナログ時計</p>
        </header>

        {/* 時計本体セクション */}
        <section className="clock-section">
          <AnalogClock
            hours={timeState.hours}
            minutes={timeState.minutes}
            seconds={timeState.seconds}
            milliseconds={timeState.milliseconds}
            movement={settings.movement}
            theme={settings.theme}
            showDate={settings.showDate}
            dateString={dateWindowText}
          />
        </section>

        {/* デジタル時刻・日付ディスプレイ（設定連動・12H/24H切り替え対応） */}
        {settings.showDigital && (
          <div className="digital-display">
            <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
              {ampmIndicator && (
                <span
                  style={{
                    fontSize: '0.875rem',
                    fontWeight: 700,
                    color: 'var(--primary-accent)',
                    letterSpacing: '0.05em',
                  }}
                >
                  {ampmIndicator}
                </span>
              )}
              <div className="digital-time">{digitalTimeStr}</div>
              <button
                type="button"
                className="btn-option"
                style={{ fontSize: '0.7rem', padding: '2px 8px', marginLeft: '4px' }}
                onClick={() => handleUpdateSettings({ is24Hour: !is24HourMode })}
                title="12時間 / 24時間表示を切り替え"
              >
                {is24HourMode ? '24H' : '12H'}
              </button>
            </div>
            <div className="digital-date">{timeState.fullDateString}</div>
          </div>
        )}

        {/* 操作パネル（メモ化により高頻度再レンダリングを回避） */}
        <MemoizedClockControls
          settings={settings}
          onUpdateSettings={handleUpdateSettings}
        />

        {/* ステータスバー */}
        <footer className="status-bar">
          <span>運針: {settings.movement === 'smooth' ? 'スイープ運針' : 'ステップ運針'}</span>
          <div className="sound-indicator">
            <span>サウンド: {settings.soundEnabled ? 'ON (チクタク)' : 'OFF'}</span>
          </div>
        </footer>
      </main>
    </div>
  );
}
